import sys

class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def area(self):
        return self.length * self.width

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    length = int(data[0])
    width = int(data[1])
    rect = Rectangle(length, width)
    print(rect.area())

if __name__ == "__main__":
    main()
